```python
"""
Python Decorators: A Comprehensive Tutorial
==========================================

This tutorial covers everything you need to know about Python decorators,
from basic concepts to advanced patterns.
"""

# ============================================================================
# 1. BASIC DECORATOR SYNTAX
# ============================================================================

print("=" * 70)
print("1. BASIC DECORATOR SYNTAX")
print("=" * 70)

# A decorator is a function that takes another function and extends its behavior
# without explicitly modifying it.

def my_decorator(func):
    """Basic decorator that wraps a function."""
    def wrapper():
        print("Something is happening before the function is called.")
        func()
        print("Something is happening after the function is called.")
    return wrapper

# Method 1: Manual decoration
def say_hello():
    print("Hello!")

say_hello = my_decorator(say_hello)
say_hello()
print()

# Method 2: Using @ syntax (syntactic sugar)
@my_decorator
def say_goodbye():
    print("Goodbye!")

say_goodbye()
print()


# Decorators with function arguments
def decorator_with_args(func):
    """Decorator that handles function arguments."""
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned: {result}")
        return result
    return wrapper

@decorator_with_args
def add(a, b):
    return a + b

result = add(5, 3)
print()


# Preserving function metadata with functools.wraps
from functools import wraps

def better_decorator(func):
    """Decorator that preserves original function metadata."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        """Wrapper function."""
        return func(*args, **kwargs)
    return wrapper

@better_decorator
def example_function():
    """This is the original docstring."""
    pass

print(f"Function name: {example_function.__name__}")
print(f"Function docstring: {example_function.__doc__}")
print()


# ============================================================================
# 2. DECORATORS WITH ARGUMENTS
# ============================================================================

print("=" * 70)
print("2. DECORATORS WITH ARGUMENTS")
print("=" * 70)

# Decorators that accept arguments need an extra layer of nesting

def repeat(times):
    """Decorator that repeats function execution."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(times):
                results.append(func(*args, **kwargs))
            return results
        return wrapper
    return decorator

@repeat(times=3)
def greet(name):
    print(f"Hello, {name}!")
    return f"Greeted {name}"

results = greet("Alice")
print(f"Results: {results}")
print()


# Decorator with optional arguments
def smart_repeat(func=None, *, times=2):
    """Decorator that can be used with or without arguments."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper

    if func is None:
        # Called with arguments: @smart_repeat(times=3)
        return decorator
    else:
        # Called without arguments: @smart_repeat
        return decorator(func)

@smart_repeat
def say_hi():
    print("Hi!")

@smart_repeat(times=4)
def say_hey():
    print("Hey!")

say_hi()
print()
say_hey()
print()


# Practical example: Timing decorator with optional precision
import time

def timer(func=None, *, precision=4):
    """Measure function execution time."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start = time.time()
            result = func(*args, **kwargs)
            end = time.time()
            elapsed = end - start
            print(f"{func.__name__} took {elapsed:.{precision}f} seconds")
            return result
        return wrapper

    if func is None:
        return decorator
    else:
        return decorator(func)

@timer
def slow_function():
    time.sleep(0.1)
    return "Done"

@timer(precision=6)
def another_slow_function():
    time.sleep(0.05)
    return "Also done"

slow_function()
another_slow_function()
print()


# ============================================================================
# 3. CLASS DECORATORS
# ============================================================================

print("=" * 70)
print("3. CLASS DECORATORS")
print("=" * 70)

# Method 1: Class as a decorator
class CountCalls:
    """Decorator class that counts function calls."""
    def __init__(self, func):
        self.func = func
        self.count = 0
        wraps(func)(self)  # Preserve metadata

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"Call {self.count} of {self.func.__name__}")
        return self.func(*args, **kwargs)

@CountCalls
def process_data(data):
    return f"Processing: {data}"

process_data("item1")
process_data("item2")
process_data("item3")
print(f"Total calls: {process_data.count}")
print()


# Method 2: Class decorator with arguments
class Retry:
    """Decorator that retries a function on failure."""
    def __init__(self, max_attempts=3, delay=1):
        self.max_attempts = max_attempts
        self.delay = delay

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(1, self.max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_exception = e
                    print(f"Attempt {attempt} failed: {e}")
                    if attempt < self.max_attempts:
                        time.sleep(self.delay)
            raise last_exception
        return wrapper

@Retry(max_attempts=3, delay=0.1)
def unreliable_function():
    import random
    if random.random() < 0.7:
        raise ValueError("Random failure!")
    return "Success!"

try:
    result = unreliable_function()
    print(f"Result: {result}")
except ValueError as e:
    print(f"All attempts failed: {e}")
print()


# Method 3: Decorating a class itself
def singleton(cls):
    """Decorator that makes a class a singleton."""
    instances = {}
    @wraps(cls)
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return get_instance

@singleton
class Database:
    def __init__(self):
        print("Initializing database connection...")
        self.connection = "Connected"

db1 = Database()
db2 = Database()
print(f"db1 is db2: {db1 is db2}")  # True
print()


# Adding methods to a class with a decorator
def add_repr(cls):
    """Decorator that adds a __repr__ method to a class."""
    def __repr__(self):
        attrs = ", ".join(f"{k}={v!r}" for k, v in self.__dict__.items())
        return f"{cls.__name__}({attrs})"
    cls.__repr__ = __repr__
    return cls

@add_repr
class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

person = Person("Bob", 30)
print(person)
print()


# ============================================================================
# 4. BUILT-IN DECORATORS
# ============================================================================

print("=" * 70)
print("4. BUILT-IN DECORATORS")
print("=" * 70)

# @property - Convert method to read-only attribute
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        """Get the radius."""
        return self._radius

    @radius.setter
    def radius(self, value):
        """Set the radius with validation."""
        if value < 0:
            raise ValueError("Radius cannot be negative")
        self._radius = value

    @property
    def area(self):
        """Calculate area (read-only property)."""
        import math
        return math.pi * self._radius ** 2

circle = Circle(5)
print(f"Radius: {circle.radius}")
print(f"Area: {circle.area:.2f}")
circle.radius = 10
print(f"New radius: {circle.radius}")
print(f"New area: {circle.area:.2f}")
print()


# @staticmethod - Method that doesn't access instance or class
class MathUtils:
    @staticmethod
    def add(a, b):
        """Add two numbers without accessing class/instance."""
        return a + b

    @staticmethod
    def multiply(a, b):
        return a * b

print(f"MathUtils.add(5, 3) = {MathUtils.add(5, 3)}")
print(f"MathUtils.multiply(4, 7) = {MathUtils.multiply(4, 7)}")
print()


# @classmethod - Method that receives class as first argument
class Employee:
    company = "TechCorp"
    employee_count = 0

    def __init__(self, name, salary):
        self.name = name
        self.salary = salary
        Employee.employee_count += 1

    @classmethod
    def from_string(cls, emp_string):
        """Alternative constructor from string."""
        name, salary = emp_string.split("-")
        return cls(name, int(salary))

    @classmethod
    def get_employee_count(cls):
        """Get total employee count."""
        return cls.employee_count

    @classmethod
    def set_company(cls, company_name):
        """Change company name for all employees."""
        cls.company = company_name

emp1 = Employee("Alice", 50000)
emp2 = Employee.from_string("Bob-60000")
print(f"Total employees: {Employee.get_employee_count()}")
print(f"Company: {Employee.company}")
print()


# @abstractmethod - Define abstract methods (requires abc module)
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self):
        """Calculate area - must be implemented by subclasses."""
        pass

    @abstractmethod
    def perimeter(self):
        """Calculate perimeter - must be implemented by subclasses."""
        pass

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

rect = Rectangle(5, 10)
print(f"Rectangle area: {rect.area()}")
print(f"Rectangle perimeter: {rect.perimeter()}")
print()


# ============================================================================
# 5. PRACTICAL EXAMPLES
# ============================================================================

print("=" * 70)
print("5. PRACTICAL EXAMPLES")
print("=" * 70)

# Example 1: Caching/Memoization decorator
def memoize(func):
    """Cache function results for performance."""
    cache = {}
    @wraps(func)
    def wrapper(*args):
        if args not in cache:
            print(f"Computing {func.__name__}{args}...")
            cache[args] = func(*args)
        else:
            print(f"Using cached result for {func.__name__}{args}")
        return cache[args]
    wrapper.cache = cache  # Expose cache for inspection
    return wrapper

@memoize
def fibonacci(n):
    """Calculate fibonacci number (slow without memoization)."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(f"fibonacci(10) = {fibonacci(10)}")
print(f"fibonacci(10) = {fibonacci(10)}")  # Uses cache
print(f"Cache size: {len(fibonacci.cache)}")
print()


# Example 2: Authentication/Authorization decorator
def require_auth(permission):
    """Decorator to check user permissions."""
    def decorator(func):
        @wraps(func)
        def wrapper(user, *args, **kwargs):
            if not hasattr(user, 'permissions'):
                raise PermissionError(f"User has no permissions")
            if permission not in user.permissions:
                raise PermissionError(f"User lacks '{permission}' permission")
            return func(user, *args, **kwargs)
        return wrapper
    return decorator

class User:
    def __init__(self, name, permissions):
        self.name = name
        self.permissions = permissions

@require_auth("delete")
def delete_file(user, filename):
    return f"{user.name} deleted {filename}"

admin = User("Admin", ["read", "write", "delete"])
regular_user = User("John", ["read"])

print(delete_file(admin, "document.txt"))
try:
    delete_file(regular_user, "document.txt")
except PermissionError as e:
    print(f"Error: {e}")
print()


# Example 3: Rate limiting decorator
from collections import deque

def rate_limit(max_calls, time_window):
    """Limit function calls to max_calls per time_window seconds."""
    def decorator(func):
        calls = deque()

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            # Remove calls outside the time window
            while calls and calls[0] < now - time_window:
                calls.popleft()

            if len(calls) >= max_calls:
                wait_time = calls[0] + time_window - now
                raise RuntimeError(
                    f"Rate limit exceeded. Try again in {wait_time:.2f} seconds"
                )

            calls.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

@rate_limit(max_calls=3, time_window=2)
def api_call(endpoint):
    return f"Called {endpoint}"

# Make allowed calls
for i in range(3):
    print(api_call(f"/api/endpoint{i}"))

# This will fail
try:
    print(api_call("/api/endpoint4"))
except RuntimeError as e:
    print(f"Error: {e}")
print()


# Example 4: Validation decorator
def validate_types(**type_checks):
    """Validate function argument types."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get function signature
            import inspect
            sig = inspect.signature(func)
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()

            # Check types
            for param_name, expected_type in type_checks.items():
                if param_name in bound.arguments:
                    value = bound.arguments[param_name]
                    if not isinstance(value, expected_type):
                        raise TypeError(
                            f"{param_name} must be {expected_type.__name__}, "
                            f"got {type(value).__name__}"
                        )

            return func(*args, **kwargs)
        return wrapper
    return decorator

@validate_types(name=str, age=int, salary=float)
def create_employee(name, age, salary):
    return f"Created employee: {name}, {age} years old, ${salary:.2f}"

print(create_employee("Alice", 30, 75000.0))
try:
    create_employee("Bob", "thirty", 80000.0)  # Wrong type for age
except TypeError as e:
    print(f"Error: {e}")
print()


# Example 5: Logging decorator with context
import logging
logging.basicConfig(level=logging.INFO, format='%(message)s')

def log_execution(level=logging.INFO):
    """Log function execution with arguments and results."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            args_repr = ", ".join(repr(a) for a in args)
            kwargs_repr = ", ".join(f"{k}={v!r}" for k, v in kwargs.items())
            signature = ", ".join(filter(None, [args_repr, kwargs_repr]))

            logging.log(level, f"Calling {func.__name__}({signature})")
            try:
                result = func(*args, **kwargs)
                logging.log(level, f"{func.__name__} returned {result!r}")
                return result
            except Exception as e:
                logging.error(f"{func.__name__} raised {e.__class__.__name__}: {e}")
                raise
        return wrapper
    return decorator

@log_execution(level=logging.INFO)
def calculate(x, y, operation="add"):
    operations = {
        "add": lambda a, b: a + b,
        "multiply": lambda a, b: a * b,
    }
    return operations[operation](x, y)

result = calculate(10, 5, operation="multiply")
print()


# Example 6: Contextual decorator with state
class Profiler:
    """Decorator that tracks execution time and call count."""
    def __init__(self):
        self.stats = {}

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if func.__name__ not in self.stats:
                self.stats[func.__name__] = {
                    'calls': 0,
                    'total_time': 0,
                    'min_time': float('inf'),
                    'max_time': 0
                }

            start = time.time()
            result = func(*args, **kwargs)
            elapsed = time.time() - start

            stats = self.stats[func.__name__]
            stats['calls'] += 1
            stats['total_time'] += elapsed
            stats['min_time'] = min(stats['min_time'], elapsed)
            stats['max_time'] = max(stats['max_time'], elapsed)

            return result
        return wrapper

    def report(self):
        """Print profiling statistics."""
        print("\nProfiling Report:")
        print("-" * 70)
        for func_name, stats in self.stats.items():
            avg_time = stats['total_time'] / stats['calls']
            print(f"{func_name}:")
            print(f"  Calls: {stats['calls']}")
            print(f"  Total time: {stats['total_time']:.4f}s")
            print(f"  Avg time: {avg_time:.4f}s")
            print(f"  Min time: {stats['min_time']:.4f}s")
            print(f"  Max time: {stats['max_time']:.4f}s")

profiler = Profiler()

@profiler
def process_item(item):
    time.sleep(0.01)
    return f"Processed {item}"

@profiler
def validate_item(item):
    time.sleep(0.005)
    return True

for i in range(5):
    validate_item(f"item{i}")
    process_item(f"item{i}")

profiler.report()
print()


# Example 7: Chaining multiple decorators
@timer
@memoize
@log_execution()
def expensive_calculation(n):
    """Simulate expensive calculation."""
    time.sleep(0.1)
    return n ** 2

print("First call:")
result1 = expensive_calculation(5)

print("\nSecond call (should use cache):")
result2 = expensive_calculation(5)
print()


print("=" * 70)
print("SUMMARY")
print("=" * 70)
print("""
Key Takeaways:
1. Decorators wrap functions to extend behavior without modifying source code
2. Use @wraps from functools to preserve function metadata
3. Decorator arguments require an extra layer of function nesting
4. Classes can be decorators and decorators can be applied to classes
5. Built-in decorators (@property, @staticmethod, @classmethod) solve common patterns
6. Practical use cases: caching, logging, authentication, validation, rate limiting

Best Practices:
- Always use @wraps to preserve function metadata
- Keep decorators focused on a single responsibility
- Make decorators reusable and composable
- Document decorator behavior clearly
- Consider performance implications of wrapper overhead
- Use type hints for better IDE support (Python 3.5+)
""")
```

This tutorial covers all aspects of Python decorators with working examples. Each section demonstrates real-world patterns you can adapt for your own projects. The examples progress from simple to complex, showing both function and class-based approaches.
